const express = require('express');
const _ = require('lodash');
const fs = require('fs');
const { execSync } = require('child_process');

const app = express();
app.use(express.json());

// Configuration store with defaults
const appConfig = {
  theme: 'light',
  locale: 'en-US',
  features: {
    analytics: true,
    notifications: true
  },
  admin: {
    enabled: false,
    shellAccess: false
  }
};

// Deep merge utility for user preferences
function deepMerge(target, source) {
  for (const key in source) {
    if (source.hasOwnProperty(key)) {
      if (typeof source[key] === 'object' && source[key] !== null && !Array.isArray(source[key])) {
        if (!target[key]) target[key] = {};
        deepMerge(target[key], source[key]);
      } else {
        target[key] = source[key];
      }
    }
  }
  return target;
}

// User preferences endpoint
app.post('/api/preferences', (req, res) => {
  const userPrefs = req.body;

  // Merge user preferences into config
  deepMerge(appConfig, userPrefs);

  res.json({ status: 'updated', config: appConfig });
});

// Admin panel - checks config for access
app.get('/api/admin/status', (req, res) => {
  if (appConfig.admin && appConfig.admin.enabled) {
    res.json({ admin: true, pid: process.pid, platform: process.platform });
  } else {
    res.status(403).json({ error: 'Admin not enabled' });
  }
});

// Debug endpoint - uses polluted prototype for RCE
app.post('/api/admin/exec', (req, res) => {
  if (!appConfig.admin || !appConfig.admin.shellAccess) {
    return res.status(403).json({ error: 'Shell access not enabled' });
  }

  const cmd = req.body.cmd;
  if (!cmd) return res.status(400).json({ error: 'No command provided' });

  try {
    // Attempt to read system info or execute commands
    const result = execSync(cmd, { timeout: 5000 }).toString();
    res.json({ output: result });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// Health check that reads /proc for container info
app.get('/api/health', (req, res) => {
  try {
    const cgroup = fs.readFileSync('/proc/self/cgroup', 'utf8');
    const isContainer = cgroup.includes('docker') || cgroup.includes('kubepods');
    res.json({ 
      healthy: true, 
      containerized: isContainer,
      uptime: process.uptime()
    });
  } catch (e) {
    res.json({ healthy: true, containerized: false, uptime: process.uptime() });
  }
});

// Template rendering with potential prototype pollution impact
app.get('/api/render', (req, res) => {
  const template = {};
  const output = {
    title: template.title || 'Default Page',
    isAdmin: template.isAdmin || false,
    rce: template.rce || null
  };
  res.json(output);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
